head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setReadOnly]<br/>파라미터에 맞게 특정 단위의 readOnly 속성값을 설정합니다.",
    "validation" : [
        "colInfo(필수) 파라미터로 Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
        readOnlyBackgroundColor: "#D3D3D3",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oncelldblclick"]);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



scwin.btn_setReadOnly_onclick = function () {
    let type = par_type.getText();
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = par_colInfo.getText();
    let readOnlyText = par_readOnly.getValue();

    let readOnly;
    let isOmit = readOnlyText === 'omit';
    if (readOnlyText === 'true') {
        readOnly = true;
    } else if (readOnlyText === 'false') {
        readOnly = false;
    } else if (readOnlyText === '') {
        readOnly = "";
    }

    if (type === 'grid') {
        if (isOmit) {
            target1.setReadOnly("grid");
            wf_body_bottom.getObj("scwin").setReturnValue("setReadOnly('grid')");
        } else {
            target1.setReadOnly("grid", readOnly);
            wf_body_bottom.getObj("scwin").setReturnValue("setReadOnly('grid', " + JSON.stringify(readOnly) + ")");
        }
    } else if (type === 'row') {
        if (isOmit) {
            target1.setReadOnly("row", rowIndex);
            wf_body_bottom.getObj("scwin").setReturnValue("setReadOnly('row', " + rowIndex + ")");
        } else {
            target1.setReadOnly("row", rowIndex, readOnly);
            wf_body_bottom.getObj("scwin").setReturnValue("setReadOnly('row', " + rowIndex + ", " + JSON.stringify(readOnly) + ")");
        }
    } else if (type === 'column') {
        if (isOmit) {
            target1.setReadOnly("column", colInfo);
            wf_body_bottom.getObj("scwin").setReturnValue("setReadOnly('column', '" + colInfo + "')");
        } else {
            target1.setReadOnly("column", colInfo, readOnly);
            wf_body_bottom.getObj("scwin").setReturnValue("setReadOnly('column', '" + colInfo + "', " + JSON.stringify(readOnly) + ")");
        }
    } else if (type === 'cell') {
        if (isOmit) {
            target1.setReadOnly("cell", rowIndex, colInfo);
            wf_body_bottom.getObj("scwin").setReturnValue("setReadOnly('cell', " + rowIndex + ", '" + colInfo + "')");
        } else {
            target1.setReadOnly("cell", rowIndex, colInfo, readOnly);
            wf_body_bottom.getObj("scwin").setReturnValue("setReadOnly('cell', " + rowIndex + ", '" + colInfo + "', " + JSON.stringify(readOnly) + ")");
        }
    }

    scwin.btn_getReadOnly_onclick();
}



scwin.btn_getReadOnly_onclick = function () {
    let type = par_type.getText();
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = par_colInfo.getText();

    let rtn;
    if (type === 'grid') {
        rtn = target1.getReadOnly("grid");
        wf_body_bottom.getObj("scwin").setReturnValue("getReadOnly('grid') : " + rtn);
    } else if (type === 'row') {
        rtn = target1.getReadOnly("row", rowIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("getReadOnly('row', " + rowIndex + ") : " + rtn);
    } else if (type === 'column') {
        rtn = target1.getReadOnly("column", colInfo);
        wf_body_bottom.getObj("scwin").setReturnValue("getReadOnly('column', '" + colInfo + "') : " + rtn);
    } else if (type === 'cell') {
        rtn = target1.getReadOnly("cell", rowIndex, colInfo);
        wf_body_bottom.getObj("scwin").setReturnValue("getReadOnly('cell', " + rowIndex + ", '" + colInfo + "') : " + rtn);
    }
}



scwin.btn_getAllCellReadOnly_onclick = function () {
    let rowCount = dlt_bind.getRowCount();
    let colCount = target1.getColumnCount();

    for (let r = 0; r < rowCount; r++) {
        let rowResult = '';
        for (let c = 0; c < colCount; c++) {
            let td = document.querySelector("td[id*='target1_cell_" + r + "_" + c + "']");
            if (td) {
                rowResult += 'cell(' + r + ',' + c + ')=' + td.readOnly + ' ';
            }
        }
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + r + " : " + rowResult);
    }
}



scwin.target1_oncelldblclick = function (row, col) {
    let isEditing = target1.isEditing();
    wf_body_bottom.getObj("scwin").setReturnValue("Cell(" + row + ", " + col + ") dblclick - isEditing : " + isEditing);
}
